using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyCorruptDiceAmountBasedAction", menuName = "Data/Battle/Battle Actions/Purification Actions/PurifyCorruptDiceAmountBased Action")]
public class PurifyCorruptDiceAmountBasedAction : PurifyCorruptWithMultiplierActions
{
	[Header("Action Specifics")]
	[SerializeField]
	[HideIf("enableDiceAmountByName")]
	private DiceTier diceTier;

	[SerializeField]
	private bool enableDiceAmountByName;

	[SerializeField]
	[ShowIf("enableDiceAmountByName")]
	private string diceName;

	[SerializeField]
	[ShowIf("enableDiceAmountByName")]
	private bool exactName;

	[SerializeField]
	[ShowIf("enableDiceAmountByName")]
	private string exactNameID;

	[Header("Dice Amount")]
	[SerializeField]
	private bool getDiceAmountOnlyFromHand;

	public DiceTier DiceTier => diceTier;

	public bool ExactName => exactName;

	public string ExactNameID => exactNameID;

	public bool GetDiceAmountOnlyFromHand => getDiceAmountOnlyFromHand;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		int num = 0;
		if (!enableDiceAmountByName)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(getDiceAmountOnlyFromHand)[diceTier.DiceTierID];
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByNameAmount(diceName, exactName);
	}
}
